import { Component } from '@angular/core';
import { LoginRequest } from '../../../core/interfaces/dto/login-request-dto';
import { AuthService } from '../../../core/services/auth';
import { Router, RouterModule } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-login',
  imports: [CommonModule, FormsModule, RouterModule],
  standalone: true,
  templateUrl: './login.html',
  styleUrl: './login.scss'
})
export class Login {
  credentials: LoginRequest = {
    email: '',
    password: ''
  };
  errorMessage = '';
  isLoading = false;
  showPassword = false;
  showWelcomeScreen = true;

  constructor(
    private authService: AuthService,
    private router: Router
  ) {}

  isMobile(): boolean {
    return window.innerWidth < 768;
  }

  togglePasswordVisibility(): void {
    this.showPassword = !this.showPassword;
  }

  onContinue(): void {
    this.showWelcomeScreen = false;
  }

  dismissKeyboard(event: Event): void {
    const target = event.target as HTMLElement;
    if (target.tagName !== 'INPUT' && target.tagName !== 'TEXTAREA') {
      (document.activeElement as HTMLElement)?.blur();
    }
  }

  // Fix for Samsung keyboard composing mode issue
  onInputChange(event: Event, field: 'email' | 'password'): void {
    const input = event.target as HTMLInputElement;
    this.credentials[field] = input.value;
  }


  onSubmit(): void {
    this.errorMessage = '';
    this.isLoading = true;

    this.authService.login(this.credentials).subscribe({
      next: () => {
        // Redirect based on user role
        if (this.authService.isSuperAdmin()) {
          this.router.navigate(['/super-admin/dashboard']);
        } else {
          this.router.navigate(['/dashboard']);
        }
      },
      error: (error) => {
        this.errorMessage = error.error?.message || 'Login failed. Please check your credentials.';
        this.isLoading = false;
      },
      complete: () => {
        this.isLoading = false;
      }
    });
  }
}